from rich._wrap import divide_line

def test_cjk_wrap():
    # CJK character 'こ' has cell_len 2.
    # If width is 1, it should be folded.
    word = "こ"
    width = 1
    # Current behavior: chop_cells returns ["", "こ"], divide_line returns [0], Text.divide([0]) returns ["", "こ"]
